use crate::{app::Desktop,ui::Route,views::{backend::Command,forms::Editor}};
use gpui_kit::{component::{button::{Button,ButtonVariants},input::Textarea,Disableable},*};
use std::collections::BTreeMap;
use vibeface_protocol::workspace::{InputControl,InputIntent,InputTarget,WorkspaceCommand};

impl Desktop {
 pub(crate) fn chat(&self,cx:&mut Context<Self>)->AnyElement{if !self.selected_conversation_loaded(){let mut page=self.page().child(self.bot_context_header(cx));if self.snapshot.cached{if let Some(bot)=self.selected_bot(){page=page.child("此Bot没有当前可用的离线消息历史。输入只使用上次验证的目标，存本机等待连接。").child(self.record_composer(bot.conversation_id.clone(),InputTarget::BotMain{bot_id:bot.bot_id.clone()},None,true,cx));}}else{page=page.child("正在读取所选Bot的对话，尚未确认的历史不会显示在这里。");}return page.into_any_element()}let mut header=div().flex().flex_wrap().gap_2().px_6().py_3().border_b_1().border_color(self.palette().border).child(self.nav("bot-settings","Bot 设置",Route::Bot,cx));if let Some(id)=self.conversation_id(){header=header.child(self.button("stop-reply","停止回复",Command::StopReply(id.clone()),cx)).child(self.button("read-context","查看当前上下文",Command::ScopeContext{conversation_id:id,target:self.selected_target.clone().unwrap_or_else(||InputTarget::BotMain{bot_id:self.selected_bot().map(|b|b.bot_id.clone()).unwrap_or_default()})},cx));}for work in &self.snapshot.conversation.works{header=header.child(Button::new(SharedString::from(format!("work-detail-{}",work.work_id))).label(format!("查看工作 {}",work.title)).on_click({let conversation_id=self.conversation_id().unwrap_or_default();let work_id=work.work_id.clone();cx.listener(move|this,_,_,cx|this.navigate(Route::Work{conversation_id:conversation_id.clone(),work_id:work_id.clone()},cx))}));if !["finished","completed"].contains(&work.state.as_str()){header=header.child(self.button(SharedString::from(format!("stop-{}",work.work_id)),format!("停止工作 {}",work.title),Command::StopWork{conversation_id:self.conversation_id().unwrap_or_default(),work_id:work.work_id.clone()},cx));}}
 let list_state=self.timeline.list.clone();let timeline=list(list_state,cx.processor(|this,index,_,cx|this.timeline_row(index,cx))).flex_1().w_full();
 let mut targets=div().flex().flex_wrap().gap_2();for(index,label)in["Bot 主对话","任务","工作补充","例行计划","频道成员","频道任务"].iter().enumerate(){targets=targets.child(Button::new(SharedString::from(format!("target-{index}"))).label(*label).on_click(cx.listener(move|this,_,_,cx|{this.target_kind=index;this.selected_target=None;this.target_revision=None;cx.notify();})));}
 let mut intents=div().flex().gap_2();for(label,intent)in[("继续",InputIntent::Continue),("新任务",InputIntent::NewTask),("延后",InputIntent::Defer)]{intents=intents.child(Button::new(label).label(label).on_click(cx.listener(move|this,_,_,cx|{this.intent=intent;cx.notify();})));}
 let composer=div().flex().flex_col().gap_3().p_4().border_t_1().border_color(self.palette().border).child(targets).child(self.target_picker(cx)).child(intents).child(Textarea::new(&self.composer).h(px(110.)).aria_label("消息内容")).child(div().flex().gap_2().child(Button::new("attach").label("添加附件").disabled(!self.snapshot.can_stage_input()).on_click(cx.listener(|this,_,window,cx|this.pick_attachment(window,cx)))).child(Button::new("send").label(if !self.snapshot.online{"保存，等待连接"}else if !self.snapshot.writable{"保存待发，等待可写状态"}else{"保存并发送"}).primary().disabled(self.sending||!self.snapshot.can_stage_input()||!self.selected_conversation_loaded()).on_click(cx.listener(|this,_,window,cx|this.send_message(window,cx))))).child(div().text_xs().child(format!("目标：{} · 意图：{:?} · {} 个附件",["Bot 主对话","任务","工作补充","例行计划","频道成员","频道任务"][self.target_kind],self.intent,self.attachments.len())));
 div().flex().flex_col().size_full().child(header).child(timeline).children(self.detail.iter().map(|(name,value)|self.row(name.clone(),value.clone()))).child(self.queued_inputs(cx)).child(composer).into_any_element()}
 pub(crate) fn timeline_row(&self,index:usize,cx:&mut Context<Self>)->AnyElement{let mut row=div().flex().flex_col().child(self.timeline.render_row(index));if let Some(message)=self.timeline.message(index){let text=message.text.clone();let mut actions=div().flex().flex_wrap().gap_2().px_6().pb_2().child(Button::new(SharedString::from(format!("copy-{}",message.message_id))).label("复制内容").on_click(move|_,_,cx|crate::host::platform::copy_text(cx,text.clone())));if let Some(conversation_id)=self.conversation_id(){if message.role=="user"&&self.snapshot.conversation.scheduler.jobs.iter().any(|job|job.message_id.as_ref()==Some(&message.message_id)&&["failed","rejected","cancelled","interrupted"].contains(&job.state.as_str())){actions=actions.child(self.ask(SharedString::from(format!("retry-{}",message.message_id)),"核对原执行后继续未完成内容",Command::RetryReply{conversation_id:conversation_id.clone(),message_id:message.message_id.clone()},cx));}for file in &message.attachments{let save=file.clone();let id=conversation_id.clone();actions=actions.child(self.button(SharedString::from(format!("preview-{}-{}",message.message_id,file.hash)),format!("预览 {}",file.name),Command::ArtifactPreview{conversation_id:conversation_id.clone(),file:file.clone(),offset:0},cx)).child(Button::new(SharedString::from(format!("download-{}-{}",message.message_id,file.hash))).label(format!("保存 {}",file.name)).on_click(cx.listener(move|this,_,_,cx|this.save_artifact(id.clone(),save.clone(),cx))));}}row=row.child(actions);}row.into_any_element()}
 pub(crate) fn save_artifact(&mut self,conversation_id:String,file:vibeface_protocol::workspace::Attachment,cx:&mut Context<Self>){let generation=self.snapshot.generation;let network=self.snapshot.network.clone();let picker=crate::host::platform::choose_save_path(cx,&std::env::temp_dir(),&file.name);cx.spawn(async move|this,cx|{match picker.await{Ok(Some(path))=>{let _=this.update(cx,|this,cx|{if this.same_view_scope(generation,&network){this.send(Command::ArtifactSave{conversation_id,file,path},cx);}});},Ok(None)=>{},Err(error)=>{let _=this.update(cx,|this,cx|{if this.same_view_scope(generation,&network){this.notice=Some(format!("保存对话框失败：{error}"));cx.notify();}});}}}).detach();}

 pub(crate) fn queued_inputs(&self,cx:&mut Context<Self>)->AnyElement{
 let mut rows=div().flex().flex_col().gap_2().px_4();let mut queue=self.snapshot.inputs.iter().filter(|q|Some(&q.conversation_id)==self.selected.as_ref()&&!q.cancelled).collect::<Vec<_>>();queue.sort_by_key(|q|q.effective_order);
 for(index,queued)in queue.iter().enumerate(){let mut row=div().flex().flex_wrap().gap_2().child(format!("{} · {}",if queued.deferred{"已延后"}else{"等待执行"},queued.input.text));for(label,action)in[("释放",InputControl::Release),("取消",InputControl::Cancel)]{row=row.child(self.button(SharedString::from(format!("queued-{}-{label}",queued.input.message_id)),label,Command::Workspace(WorkspaceCommand::ControlInput{message_id:queued.input.message_id.clone(),expected_event:queued.control_event.clone(),action}),cx));}
 if index>0{row=row.child(self.button(SharedString::from(format!("queued-up-{}",queued.input.message_id)),"上移",Command::Workspace(WorkspaceCommand::ControlInput{message_id:queued.input.message_id.clone(),expected_event:queued.control_event.clone(),action:InputControl::Move{before_message_id:Some(queue[index-1].input.message_id.clone())}}),cx));}
 if index+1<queue.len(){row=row.child(self.button(SharedString::from(format!("queued-down-{}",queued.input.message_id)),"下移",Command::Workspace(WorkspaceCommand::ControlInput{message_id:queued.input.message_id.clone(),expected_event:queued.control_event.clone(),action:InputControl::Move{before_message_id:queue.get(index+2).map(|q|q.input.message_id.clone())}}),cx));}
 row=row.child(self.open_editor(SharedString::from(format!("queued-edit-{}",queued.input.message_id)),"编辑输入",Editor::QueuedEdit((*queued).clone()),BTreeMap::from([("text",queued.input.text.clone())]),cx));rows=rows.child(row);}rows.into_any_element()
 }

 pub(crate) fn target_picker(&self,cx:&mut Context<Self>)->AnyElement{
 let mut choices:Vec<(String,InputTarget,Option<u64>)>=vec![];
 match self.target_kind{1=>for task in &self.snapshot.tasks{choices.push((task.title.clone(),InputTarget::Task{task_id:task.task_id.clone()},Some(task.revision)));},2=>for work in &self.snapshot.conversation.works{choices.push((work.title.clone(),InputTarget::Work{work_id:work.work_id.clone()},None));},3=>if let Some(bot)=self.selected_bot(){for job in &self.snapshot.conversation.scheduler.scope_jobs{if let crate::ui::Scope::Routine{trigger}=&job.scope{choices.push((format!("例行任务 {trigger}"),InputTarget::Routine{bot_id:bot.bot_id.clone(),trigger:trigger.clone()},None));}}},4=>for channel in &self.snapshot.channels{for member in &channel.members{let name=self.snapshot.bots.iter().find(|b|&b.bot_id==member).map(|b|b.name.as_str()).unwrap_or(member);choices.push((format!("{} / {}",channel.title,name),InputTarget::ChannelMember{channel_id:channel.channel_id.clone(),bot_id:member.clone()},None));}},5=>for channel in &self.snapshot.channels{for task in &self.snapshot.tasks{if task.channel_id.as_ref()==Some(&channel.channel_id)&&channel.members.contains(&task.owner_bot){choices.push((format!("{} / {}",channel.title,task.title),InputTarget::ChannelTask{channel_id:channel.channel_id.clone(),task_id:task.task_id.clone(),bot_id:task.owner_bot.clone()},Some(task.revision)));}}},_=>{}}
 let mut picker=div().flex().flex_wrap().gap_2();for(index,(label,target,revision))in choices.into_iter().enumerate(){let selected=self.selected_target.as_ref()==Some(&target);picker=picker.child(Button::new(SharedString::from(format!("target-choice-{index}"))).label(if selected{format!("已选：{label}")}else{label}).on_click(cx.listener(move|this,_,_,cx|{this.selected_target=Some(target.clone());this.target_revision=revision;cx.notify();})));}picker.into_any_element()
 }
 pub(crate) fn pick_attachment(&mut self,_:&mut Window,cx:&mut Context<Self>){let Some(scope)=self.attachment_scope.clone().or_else(||self.conversation_id())else{self.notice=Some("请先选择消息目标。".into());return};let generation=self.snapshot.generation;let network=self.snapshot.network.clone();let dialog=cx.prompt_for_paths(PathPromptOptions{files:true,directories:false,multiple:true,prompt:Some("选择附件".into())});cx.spawn(async move|this,cx|{if let Ok(Ok(Some(paths)))=dialog.await{let _=this.update(cx,|this,cx|{if this.same_view_scope(generation,&network)&&this.attachment_scope.as_ref()==Some(&scope){this.send(Command::Attachments{conversation_id:scope,paths},cx);}});}}).detach();}

}
